		fmt.Fprintf(os.Stderr, "Usage: %s N\n", os.Args[0])
		os.Exit(1)
	}

	N, err := fmt.Sscanf(os.Args[1], "%d", nil)
	if err != nil || N != 1 {
		fmt.Fprintf(os.Stderr, "Error parsing argument: %s\n", os.Args[1])
		os.Exit(1)
	}

	// Validate input range
	if N < 2 {
		// No primes below 2
		return
	}

	// Collect primes
	var primes []int
	for i := 2; i <= N; i++ {
		if isPrime(i) {
			primes = append(primes, i)
		}
	}

	// Output primes
	for _, p := range primes {
		fmt.Println(p)
	}
}
